import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { remember, t } from '../util';
import { destroy, ICONS, list } from './api';
import { composerStances, insertMarker, markerIds, removeMarker } from '../composer';
import StanceModal from './StanceModal';
/**
 * The composer pill's list: this post's blocks, whether each is in the text, and add, edit,
 * put back or take out. Taking a block out of the text hides it (its votes are kept); a draft
 * nobody posted is deleted.
 */
export default class ComposerModal extends Modal {
  loading = false;
  oninit(vnode) {
    super.oninit(vnode);
    const attrs = this.attrs.composer.body.attrs;
    // Editing a post: fetch its blocks once, hidden ones too.
    if (attrs.post && !attrs.stancesLoaded) {
      this.loading = true;
      list({
        filter: {
          post: attrs.post.id()
        }
      }).then(r => {
        const own = composerStances(this.attrs.composer);
        for (const s of r.rows) if (!own.some(x => x.id === s.id)) own.push(remember(s));
        attrs.stancesLoaded = true;
      }).catch(() => {}).finally(() => {
        this.loading = false;
        m.redraw();
      });
    }
  }
  className() {
    return 'StanceComposerModal Modal--small';
  }
  title() {
    return t('composer.list_title');
  }
  content() {
    const composer = this.attrs.composer;
    const list = composerStances(composer);
    const inText = markerIds(composer);
    const max = Number(app.forum.attribute('stancesMaxPerPost') || 3);
    const showing = list.filter(s => inText.includes(s.id)).length;
    return m("div", {
      className: "Modal-body"
    }, this.loading ? m(LoadingIndicator, null) : null, list.length ? m("ul", {
      className: "StanceComposerModal-list"
    }, list.map(s => {
      const present = inText.includes(s.id);
      return m("li", {
        className: "StanceComposerModal-item"
      }, m(Icon, {
        name: ICONS[s.type]
      }), m("div", {
        className: "StanceComposerModal-text"
      }, m("span", {
        className: "StanceComposerModal-question"
      }, s.question), m("span", {
        className: "StanceComposerModal-status"
      }, present ? t('composer.in_text') : t('composer.not_in_text'), s.voteCount ? ' · ' + t('card.votes', {
        count: s.voteCount
      }) : '')), m("div", {
        className: "StanceComposerModal-actions"
      }, s.canEdit && !s.closed ? m(Button, {
        className: "Button Button--icon Button--flat",
        icon: "fas fa-pencil-alt",
        "aria-label": t('menu.edit'),
        onclick: () => this.edit(s)
      }) : null, present ? m(Button, {
        className: "Button Button--icon Button--flat",
        icon: "fas fa-eye-slash",
        "aria-label": t('composer.take_out'),
        onclick: () => this.takeOut(s)
      }) : m(Button, {
        className: "Button Button--icon Button--flat",
        icon: "fas fa-plus",
        "aria-label": t('composer.put_back'),
        disabled: showing >= max,
        onclick: () => {
          insertMarker(composer, s.id);
          m.redraw();
        }
      })));
    })) : m("p", {
      className: "StanceComposerModal-empty"
    }, t('composer.empty')), m("p", {
      className: "helpText"
    }, t('composer.marker_help')), m(Button, {
      className: "Button Button--primary Button--block",
      icon: "fas fa-plus",
      disabled: showing >= max,
      onclick: () => this.add()
    }, showing >= max ? t('composer.limit', {
      count: max
    }) : t('composer.add')));
  }
  add() {
    openAdd(this.attrs.composer);
  }
  edit(s) {
    const composer = this.attrs.composer;
    app.modal.show(StanceModal, {
      stance: s,
      onsave: saved => {
        const list = composerStances(composer);
        const i = list.findIndex(x => x.id === saved.id);
        if (i >= 0) list[i] = saved;
        app.modal.show(ComposerModal, {
          composer
        });
      }
    });
  }
  takeOut(s) {
    const composer = this.attrs.composer;
    removeMarker(composer, s.id);
    if (s.postId === null) {
      // A draft no post has claimed: nothing to keep.
      destroy(s.id).catch(() => {});
      const list = composerStances(composer);
      list.splice(list.indexOf(s), 1);
    }
    m.redraw();
  }
}

/** The dialog for a new block; saving puts its marker at the cursor. */
export function openAdd(composer) {
  const discussion = composer.body.attrs.discussion || composer.body.attrs.post?.discussion?.();
  app.modal.show(StanceModal, {
    discussionId: discussion ? Number(discussion.id()) : null,
    onsave: saved => {
      composerStances(composer).push(saved);
      insertMarker(composer, saved.id);
    }
  });
}
flarum.reg.add('ernestdefoe-stances', 'forum/components/ComposerModal', ComposerModal);